// ExamPage.js
import React, { useState, useEffect } from "react";
import './ExamPage.css';

const ExamPage = () => {
  const [timeLeft, setTimeLeft] = useState(300); // 5 minutes timer (300 seconds)
  const [answers, setAnswers] = useState({
    q1: "",
    q2: "",
    q3: "",
  });
  const [isTimeUp, setIsTimeUp] = useState(false); // State to track if time is up

  useEffect(() => {
    if (timeLeft === 0) {
      setIsTimeUp(true); // Set time-up state when the timer reaches zero
      return;
    }

    const timer = setInterval(() => {
      setTimeLeft((prevTime) => prevTime - 1);
    }, 1000);

    return () => clearInterval(timer); // Clear the timer on cleanup
  }, [timeLeft]);

  const handleChange = (e) => {
    if (!isTimeUp) { // Prevent changes when time is up
      setAnswers({
        ...answers,
        [e.target.name]: e.target.value,
      });
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!isTimeUp) {
      alert("Exam submitted! Your answers have been saved.");
      // Add logic to submit answers to a server or store locally
    } else {
      alert("Time's up! You can't submit the exam.");
    }
  };

  return (
    <div className="exam-container">
      <h2>Exam</h2>
      <div className="timer">
        <p>Time Left: {Math.floor(timeLeft / 60)}:{timeLeft % 60}</p>
      </div>

      {isTimeUp && <p className="time-up">Time's up! You can no longer modify or submit your answers.</p>}

      <form onSubmit={handleSubmit} className="exam-form">
        <div className="question">
          <label>1. What is 2 + 2?</label>
          <input
            type="text"
            name="q1"
            value={answers.q1}
            onChange={handleChange}
            disabled={isTimeUp} // Disable input if time is up
            required
          />
        </div>

        <div className="question">
          <label>2. What is the capital of France?</label>
          <input
            type="text"
            name="q2"
            value={answers.q2}
            onChange={handleChange}
            disabled={isTimeUp} // Disable input if time is up
            required
          />
        </div>

        <div className="question">
          <label>3. Who was the first president of the United States?</label>
          <input
            type="text"
            name="q3"
            value={answers.q3}
            onChange={handleChange}
            disabled={isTimeUp} // Disable input if time is up
            required
          />
        </div>

        <button type="submit" className="submit-btn" disabled={isTimeUp}>Submit Exam</button>
      </form>
    </div>
  );
};

export default ExamPage;
